/* HEXA BATTLEGROUNDS setup — PART 12 OF 20. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-orders-food-3', 'orders', 'mission', 'Mess Hall Ledger', 'memory', 1, array['food','healing','market']::text[], 'Squad 00 swapped the bills. Calculate the correct total for the order your intel points to and enter the number.', '{"scout":{"title":"Order slips on the counter","body":"Table 6: 1× Paneer Roll, 3× Juice\nTable 2: 1× Meals, 2× Dosa\nTable 11: 3× Idli, 2× Paneer Roll, 2× Curd Rice\nTable 4: 2× Curd Rice, 3× Meals, 1× Idli","mono":true},"decoder":{"title":"Canteen price board","body":"Biryani — 18\nDosa — 10\nIdli — 6\nMeals — 15\nPaneer Roll — 12\nJuice — 7\nCurd Rice — 9\nVada — 5","mono":true},"intel":{"title":"Billing intel","body":"Bill Table 11.\nHouse rule today: add 5 coins for takeaway packing (once per order)."}}'::jsonb, '[{"label":"Total","accept":["65"]}]'::jsonb, false, 3, 200, 'Multiply each quantity by its price, add them, then apply the house rule.', 'Table 11 with the rule applied totals 65.', null, 25, 'published'), ('mission-orders-food-4', 'orders', 'mission', 'Mess Hall Ledger', 'memory', 1, array['food','healing','market']::text[], 'Squad 00 swapped the bills. Calculate the correct total for the order your intel points to and enter the number.', '{"scout":{"title":"Order slips on the counter","body":"Table 7: 3× Juice, 2× Dosa, 1× Vada\nTable 4: 1× Biryani, 3× Juice\nTable 8: 3× Meals, 1× Vada, 3× Biryani\nTable 11: 1× Dosa, 2× Biryani","mono":true},"decoder":{"title":"Canteen price board","body":"Biryani — 18\nDosa — 10\nIdli — 6\nMeals — 15\nPaneer Roll — 12\nJuice — 7\nCurd Rice — 9\nVada — 5","mono":true},"intel":{"title":"Billing intel","body":"Bill Table 8.\nCorrection: the Meals quantity on that slip was written as half. Double it."}}'::jsonb, '[{"labe