HER"]},{"label":"Panel 2 (Decoder)","accept":["MINDOVERMATTER"]},{"label":"Panel 3 (Intel)","accept":["IUNDERSTAND"]}]'::jsonb, false, 3, 200, 'Look at the position of each word: over, under, split, repeated, reversed, going down.', 'STEPFATHER: The letters go down like steps. | MIND OVER MATTER: MIND sits over MATTER. | I UNDERSTAND: I is under STAND.', null, 25, 'published'), ('mission-rebus-1', 'rebus', 'mission', 'Triple Rebus', 'rebus', 1, array['any','learning','social','office','coffee']::text[], 'Each teammate holds one picture-word puzzle. Solve all three and enter each answer in its box.', '{"scout":{"title":"Rebus panel 1","body":"  HEAD\n ──────\n HEELS","mono":true},"decoder":{"title":"Rebus panel 2","body":"   MAN\n ───────\n  BOARD","mono":true},"intel":{"title":"Rebus panel 3","body":"T\nO\nU\nC\nH","mono":true}}'::jsonb, '[{"label":"Panel 1 (Scout)","accept":["HEADOVERHEELS"]},{"label":"Panel 2 (Decoder)","accept":["MANOVERBOARD"]},{"label":"Panel 3 (Intel)","accept":["TOUCHDOWN"]}]'::jsonb, false, 3, 200, 'Look at the position of each word: over, under, split, repeated, reversed, going down.', 'HEAD OVER HEELS: HEAD sits over HEELS. | MAN OVERBOARD: MAN is over BOARD. | TOUCHDOWN: TOUCH is written going down.', null, 25, 'published'), ('mission-rebus-2', 'rebus', 'mission', 'Triple Rebus', 'rebus', 1, array['any','learning','social','office','coffee']::text[], 'Each teammate holds one picture-word puzzle. Solve all three and enter each answer in its box.', '{"scout":{"title":"Rebus panel 1","body":"BAN     ANA","mono":true},"decoder":{"title":"Rebus panel 2","body":"  STOOD\n ───────\n   MIS","mono":true},"intel":{"title":"Rebus panel 3","body":"CYCLE  CYCLE  CYCLE","mono":true}}'::jsonb, '[{"label":"Panel 1 (Scout)","accept":["BANANASPLIT","SPLITBANANA"]},{"label":"Panel 2 (Decoder)","accept":["MISUNDERSTOOD"]},{"label":"Panel 3 (Intel)","accept":["TRICYCLE","THREECYCLES"]}]'::jsonb, false, 3, 200, 'Look at the position of each word: over, under, split, repeated, reversed, going down.', 'BANANA SPLIT: The word BANANA is split. | MISUNDERSTOOD: MIS is under STOOD. | TRICYCLE: Three cycles.', null, 25, 'published'), ('mission-rebus-3', 'rebus', 'mission', 'Triple Rebus', 'rebus', 1, array['any','learning','social','office','coffee']::text[], 'Each teammate holds one picture-word puzzle. Solve all three and enter each answer in its box.', '{"scout":{"title":"Rebus panel 1","body":"DICE    DICE","mono":true},"decoder":{"title":"Rebus panel 2","body":"LE     VEL","mono":true},"intel":{"title":"Rebus panel 3","body":"  WORK\n ──────\n  TIME","mono":true}}'::jsonb, '[{"label":"Panel 1 (Scout)","accept":["PARADISE","PAIROFDICE"]},{"label":"Panel 2 (Decoder)","accept":["SPLITLEVEL"]},{"label":"Panel 3 (Intel)","accept":["WORKOVERTIME","OVERTIMEWORK"]}]'::jsonb, false, 3, 200, 'Look at the position of each word: over, under, split, repeated, reversed, going down.', 'PARADISE: A pair of dice sounds like paradise. | SPLIT LEVEL: LEVEL is split. | WORK OVERTIME: WORK is over TIME.', null, 25, 'published'), ('mission-rebus-4', 'rebus', 'mission', 'Triple Rebus', 'rebus', 1, array['any','learning','social','office','coffee']::text[], 'Each teammate holds one picture-word puzzle. Solve all three and enter each answer in its box.', '{"scout":{"title":"Rebus panel 1","body":"E C N A L G","mono":true},"decoder":{"title":"Rebus panel 2","body":"D\nU\nC\nK","mono":true},"intel":{"title":"Rebus panel 3","body":"HISTORY  HISTORY","mono":true}}'::jsonb, '[{"label":"Panel 1 (Scout)","accept":["BACKWARDGLANCE","BACKWARDSGLANCE"]},{"label":"Panel 2 (Decoder)","accept":["DUCKDOWN"]},{"label":"Panel 3 (Intel)","accept":["HISTORYREPEATSITSELF","HISTORYREPEATS","REPEATEDHISTORY"]}]'::jsonb, false, 3, 200, 'Look at the position of each word: over, under, split, repeated, reversed, going down.', 'BACKWARD GLANCE: GLANCE written backward. | DUCK DOWN: DUCK is written going down. | HISTORY REPEATS ITSELF: HISTORY repeats.', null, 25, 'published'), ('mission-anagram-0', 'anagram', 'mission', 'Corporate Scramble', 'office', 1, array['office','hr','boardroom','parking','social']::text[], 'Squad 00 shredded a meeting memo into three strips. Unscramble each strip and enter the buzzwords.', '{"scout":{"title":"Shredded memo strip 1","body":"I E D L N A D E\n\n(One office buzzword, letters scrambled.)","mono":true},"decoder":{"title":"Shredded memo strip 2","body":"E I N I V C O\n\n(One office buzzword, letters scrambled.)","mono":true},"intel":{"title":"Shredded memo strip 3","body":"E V E E R L G A\n\n(One office buzzword, letters scrambled.)","mono":true}}'::jsonb, '[{"label":"Strip 1 (Scout)","accept":["DEADLINE"]},{"label":"Strip 2 (Decoder)","accept":["INVOICE"]},{"label":"Strip 3 (Intel)","accept":["LEVERAGE"]}]'::jsonb, false, 3, 200, 'First letters: D, I, L.', 'DEADLINE, INVOICE, LEVERAGE', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();
